102	// writeDescriptor writes the descriptor of a bench that was provisioned. It is
103	// called after a successful Provision only: a partial result is never described.
104	func (s *session) writeDescriptor(deployed nexusbench.DeployResult, provisioned nexusbench.ProvisionResult) int {
105		path := s.descriptorPath()
106		if err := nexusbench.WriteDescriptor(path, nexusbench.BuildDescriptor(s.p, deployed, provisioned)); err != nil {
107			return s.fail(err)
108		}
109		_, _ = fmt.Fprintf(s.stdout, "nexus-bench: descriptor written to %s\n", path)
110		if !describesDefaultBench(s.p) {
111			s.warn("descriptor.json now describes a non-default bench; do not commit it")
112		}
113		return exitOK
114	}
