116	// describesDefaultBench tells whether p is the bench the versioned descriptor
117	// describes. The timeouts, the paths and the EULA consent do not change what
118	// the bench is, so they are left out.
119	func describesDefaultBench(p nexusbench.Params) bool {
120		normalize := func(p nexusbench.Params) nexusbench.Params {
121			p.Timeout, p.DeleteTimeout = 0, 0
122			p.SecretsPath, p.DescriptorPath = "", ""
123			p.AcceptEULA = false
124			if len(p.Hosts) == 0 {
125				p.Hosts = nil
126			}
127			return p
128		}
129		return reflect.DeepEqual(normalize(p), normalize(nexusbench.Defaults()))
130	}
